from pathlib import Path
from contextlib import closing
from collections import Counter
import sqlite3, tempfile, json, subprocess, sys, importlib.util
import vault

root=Path.cwd()
spec=importlib.util.spec_from_file_location('original_vault', root/'.baseline/vault.py')
original=importlib.util.module_from_spec(spec)
spec.loader.exec_module(original)

def snap(path):
    with closing(sqlite3.connect(path)) as con:
        return {table:Counter(con.execute('SELECT * FROM '+table)) for table in ('accounts','transfers','audit')}

with tempfile.TemporaryDirectory(prefix='.review-boundary-', dir=root) as tmp:
    for collision in (False, True):
        path=Path(tmp)/('unique-'+str(collision)+'.sqlite')
        vault.init_db(path)
        with closing(sqlite3.connect(path)) as con, con:
            con.executemany('INSERT INTO accounts VALUES (?,?,?)',[('one','a',100),('one','b',0),('two','a',800)])
            con.execute(\"INSERT INTO audit VALUES ('two','historic','x','y',?)\", (10 if collision else 9,))
            con.executescript('''
              CREATE UNIQUE INDEX audit_amount ON audit(amount);
              CREATE TRIGGER audit_via_replace BEFORE INSERT ON audit BEGIN
                INSERT OR REPLACE INTO audit VALUES (NEW.tenant,NEW.key,NEW.source,NEW.target,NEW.amount);
                SELECT RAISE(IGNORE);
              END;
            ''')
        before=snap(path)
        try:
            result={'receipt':vault.transfer(path,'one','a','b',10,'new')}
        except Exception as exc:
            result={'exception':type(exc).__name__,'message':str(exc)}
        after=snap(path)
        print(json.dumps({'probe':'secondary_unique_replace','collision':collision,'unchanged':before==after,
                          'audit_rows':list(after['audit'].elements()),**result}))

    for label, module in [('original',original),('candidate',vault)]:
        path=Path(tmp)/(label+'-dollar.sqlite')
        vault.init_db(path)
        with closing(sqlite3.connect(path)) as con, con:
            con.executemany('INSERT INTO accounts VALUES (?,?,?)',[('one','a',100),('one','b',0)])
            con.execute('CREATE TRIGGER audit"'$guard BEFORE INSERT ON audit BEGIN SELECT 1; END'"')
        try:
            result={'receipt':module.transfer(path,'one','a','b',10,'new')}
        except Exception as exc:
            result={'exception':type(exc).__name__,'message':str(exc)}
        print(json.dumps({'probe':'dollar_trigger_baseline_comparison','version':label,**result}))
        if label=='candidate':
            cli=subprocess.run([sys.executable,'-B','app.py',str(path),json.dumps({'op':'transfer','tenant':'one','source':'a','target':'b','amount':10,'key':'new'})],capture_output=True,text=True,timeout=10)
            print(json.dumps({'probe':'dollar_trigger_cli','returncode':cli.returncode,'stdout':cli.stdout,'stderr':cli.stderr}))
PY"

